def load256(pid):
    im = Image.open(f'practice/images/{pid}.jpg').convert('RGB').resize((256,256), Image.BILINEAR)
    return np.asarray(im)

def corner_tile(a, p=64):
    # a: 256x256x3. Build 256x256 from 4 corners, each mirrored 2x2 so the original corner stays in place.
    TL = a[:p,:p]; TR = a[:p,-p:]; BL = a[-p:,:p]; BR = a[-p:,-p:]
    def quad(P, corner):
        # place P at the given corner of a 2p x 2p quadrant, mirror the rest
        if corner=='TL': top = np.concatenate([P, P[:,::-1]],1); 
        if corner=='TR': top = np.concatenate([P[:,::-1], P],1)
        if corner in ('TL','TR'): return np.concatenate([top, top[::-1]],0)
        if corner=='BL': bot = np.concatenate([P, P[:,::-1]],1)
        if corner=='BR': bot = np.concatenate([P[:,::-1], P],1)
        return np.concatenate([bot[::-1], bot],0)
    top = np.concatenate([quad(TL,'TL'), quad(TR,'TR')],1)
    bot = np.concatenate([quad(BL,'BL'), quad(BR,'BR')],1)
    return np.concatenate([top,bot],0)

